"""Generate editable Polish documents from verified machine-readable results."""
from pathlib import Path
import html
import json

ROOT = Path(__file__).resolve().parents[1]
TESTS = json.loads((ROOT / 'results/tests.json').read_text())
BROWSER = json.loads((ROOT / 'results/browser.json').read_text())
BENCH = json.loads((ROOT / 'results/benchmark.json').read_text())
REPO = 'https://github.com/EdvinZe/asd1-m2-13-stagewise'
AUTHOR = 'Edvin Zenevič'
E = html.escape


def table(headers, rows, caption):
    return '<table><caption>' + caption + '</caption><thead><tr>' + ''.join(f'<th>{E(str(x))}</th>' for x in headers) + '</tr></thead><tbody>' + ''.join('<tr>' + ''.join(f'<td>{E(str(x))}</td>' for x in row) + '</tr>' for row in rows) + '</tbody></table>'


def box(text):
    return f'<div class="callout">{text}</div>'


def figure(file, caption, height=240):
    return f'<figure><img src="{file}" style="max-height:{height}px" alt="{E(caption)}"><figcaption>{caption}</figcaption></figure>'


def code(text):
    return '<pre>' + E(text) + '</pre>'


sort_code = '''dla i = 1 … n−1:
    klucz = lista[i]; j = i−1
    dopóki j ≥ 0:
        licznik += 1
        jeżeli porównaj(lista[j], klucz) ≤ 0: przerwij
        lista[j+1] = lista[j]; j = j−1
    lista[j+1] = klucz'''
search_code = '''sprawdzone = 0
dla rekord w próbach:
    sprawdzone += 1
    jeżeli rekord.id == ID: zwróć rekord, sprawdzone
zwróć brak, sprawdzone'''

benchmark_table = table(['n', 'Dane', 'Porównania', 'Wzorzec'], [[x['size'], x['kind'], x['comparisons'], 'zgodny'] for x in BENCH['results']], 'Tabela 5. Liczniki własnego sortowania; niezależny wzorzec Array.sort.')
search_table = table(['n', 'Początek', 'Koniec', 'Brak'], [[x['size'], x['first'], x['last'], x['missing']] for x in BENCH['search']], 'Tabela 6. Faktycznie sprawdzone rekordy wyszukiwania.')

report = [
('Stagewise', f'''<div class="cover"><div class="cover-brands"><img class="cover-mark" src="../assets/mark.svg" alt="Znak Stagewise"><img class="cover-filia" src="../assets/uwb-vilnius.png" alt="Filia UwB w Wilnie"><img class="cover-seal" src="../assets/uwb-seal.png" alt="Herb Uniwersytetu w Białymstoku"></div><p class="kicker">ALGORYTMY I STRUKTURY DANYCH I</p><h1>Trener wystąpień<br>publicznych<span>.</span></h1><p class="lead">Od planu do świadomej próby.<br>Od liczb do konkretnego wniosku.</p><div class="cover-line"></div><dl><dt>Autor / student</dt><dd>{AUTHOR}</dd><dt>Praca</dt><dd>Mini-projekt M2 · ASD1-M2-13</dd><dt>Rok akademicki</dt><dd>2026/2027 · praca indywidualna</dd><dt>Wersja oddania</dt><dd>m2-v1.0.0 · tag identyfikujący commit</dd></dl><p class="repo"><a href="{REPO}">{REPO}</a></p><p class="small">Dokumentacja · 10 stron · 19 listopada 2026<br>Opracowanie z pomocą AI; zakres i weryfikacja na stronie 10.</p></div>'''),
('Cel, odbiorca i zakres', '''<p>Aplikacja pomaga studentowi przygotować wystąpienie o przewidywalnym czasie i dobrych proporcjach. Użytkownik planuje części, ćwiczy, zapisuje wyniki oraz otrzymuje informację, które fragmenty wymagają największej korekty. Interfejs nie ocenia jakości wypowiedzi, lecz zgodność rozłożenia czasu z własnym planem.</p><h2>Scenariusz użytkownika</h2><p>Student przygotowuje pięciominutową prezentację. Wstęp ma trwać 60 s, treść 180 s, a zakończenie 60 s. Pierwsza próba przekracza plan. Po skróceniu rozwinięcia student zapisuje drugą próbę, porównuje wyniki i wybiera konkretny fragment do dalszego ćwiczenia.</p><h2>Zrealizowane funkcje</h2><ul><li>Wiele wystąpień z tytułem, własnym ID i uporządkowanym planem.</li><li>Dodawanie, przesuwanie i usuwanie części; planowane sekundy.</li><li>Stoper start/stop z możliwością wznowienia oraz ręczne wpisy.</li><li>Wiele kompletnych prób z numerem, czasami i notatką; edycja.</li><li>Porównanie każdej części oraz czasu całkowitego z planem.</li><li>Ranking rozbieżności i porównanie dwóch wybranych prób.</li><li>Własne wyszukiwanie liniowe i sortowanie przez wstawianie.</li><li>Liczniki operacji, rzeczywisty ślad i doświadczenia 10/100/1000.</li><li>Wersjonowany import/eksport JSON i pomocniczy zapis lokalny.</li><li>Trzy scenariusze oraz dobrowolny wykres zmian zgodności.</li></ul><h2>Kryterium sukcesu</h2><p>Po jednej kompletnej próbie użytkownik zna największe odchylenie, jego kierunek i możliwą korektę. Po dwóch próbach widzi, czy suma rozbieżności zmalała. Gdy wyniki są równe, aplikacja podaje remis zamiast arbitralnego zwycięzcy.</p>''' + box('Demonstracja działa lokalnie po rozpakowaniu. Aplikacja nie wymaga konta, serwera, mikrofonu, płatnego API ani połączenia z internetem.')),
('Reguły i model danych', '''<p>Zestaw jest obiektem JSON z polami <code>format="stagewise"</code>, <code>version=1</code> i trzema tablicami rekordów. Relacje wskazują identyfikatory, a nie pozycje w tablicy. Każdy rodzaj ma limit 1000 rekordów w całym zestawie.</p>''' + table(['Rekord', 'Pola', 'Przykład'], [
['Wystąpienie', 'id, title', 'S-KONTROLA, Moje pierwsze wystąpienie'],
['Część', 'id, speechId, order, name, plannedSeconds', 'P-WSTEP, S-KONTROLA, 1, Wstęp, 60'],
['Próba', 'id, speechId, number, actualSeconds, note', 'A, S-KONTROLA, 1, {P-WSTEP:70,…}, notatka']
], 'Tabela 1. Rekordy i relacje.') + '''<h2>Walidacja całego zestawu</h2><p>ID są niepuste, unikalne w całym zestawie i niezmienne podczas edycji rekordu. Aplikacja generuje je lokalnie z prefiksu i UUID. Import dopuszcza 1–80 znaków A–Z, cyfr i łączników. Tytuł ma 1–160 znaków, nazwa części 1–100, a notatka do 4000 znaków.</p><p>Plan części to całkowite 1–3600 s, wykonanie to całkowite 0–7200 s. Zero oznacza pominiętą część, nie brak wpisu. Części mają kolejność 1…n bez luk i duplikatów. Próba zawiera dokładnie po jednym czasie dla wszystkich części tego wystąpienia. Numery prób są dodatnie i unikalne w wystąpieniu; nowy numer to największy zapisany plus jeden.</p><h2>Niezmienniki i bezpieczeństwo stanu</h2><p>Niekompletna próba pozostaje wyłącznie roboczym formularzem. Zmiana części planu wymaga nowego wystąpienia albo potwierdzonego usunięcia jego prób. Zmiana samego tytułu nie usuwa historii. Import sprawdza cały kandydat przed pytaniem o zastąpienie. Odrzucenie nie modyfikuje bieżącego zestawu.</p>''' + box('Δᵢ = wykonanieᵢ − planᵢ; wynik = Σ|Δᵢ|. Dodatnie Δ oznacza przekroczenie. Teksty użytkownika są kodowane przy wyświetlaniu, nie wykonywane jako HTML.')),
('Algorytmy i koszty', '''<p>Dla p części jedna pętla oblicza Δ, sumę planu, sumę wykonania i Σ|Δ|. Koszt czasu wynosi O(p). Ranking powstaje we własnej funkcji <code>insertionSort</code>. Porównanie kluczy daje pierwszeństwo większemu |Δ|, a przy równości mniejszej kolejności części.</p>''' + code(sort_code) + '''<p>Posortowany prefiks rozszerza się o jeden klucz. Przesuwamy w prawo rekordy, które powinny znaleźć się za kluczem. Najlepszy przypadek: p−1 porównań, O(p). Najgorszy: p(p−1)/2, O(p²). Zwracana kopia listy zajmuje O(p); sam mechanizm przesuwania potrzebuje stałej liczby zmiennych.</p>''' + table(['Przed', 'Decyzja', 'Po'], [
['[W,T,Z], klucz=T', '|10| < |20|: przesuń W', '[W,W,Z], klucz=T'],
['[W,W,Z]', 'wstaw T na indeks 0', '[T,W,Z]'],
['[T,W,Z], klucz=Z', '|10|=|−10|, W wcześniej: stop', '[T,W,Z]']
], 'Tabela 2. Przykład A: W=wstęp, T=treść, Z=zakończenie; 2 porównania.') + code(search_code) + '''<p>Wyszukiwanie zwraca pierwsze dopasowanie. Licznik rośnie przy faktycznie sprawdzonym rekordzie. Początek listy wymaga jednego sprawdzenia, koniec i brak wyniku — n; czas O(n), pamięć dodatkowa O(1). Ślad sortowania kopiuje stan na potrzeby objaśnienia i jest dodatkowym narzutem, dlatego UI ogranicza go do 12 części.</p>'''),
('Technologie i uruchomienie', '''<h2>Bez zależności w aplikacji</h2><p>HTML, CSS i klasyczny JavaScript pozwalają uruchomić produkt bez budowania i bez sieci. Lokalne SVG są kodowymi zasobami interfejsu. Nie ma frameworka, zewnętrznych fontów ani bibliotek sortujących w głównej ścieżce. Moduły przeglądarkowe udostępniają jawne przestrzenie nazw; logika domenowa działa również w Node.js.</p><h2>Uruchomienie z czystej kopii</h2>''' + code(f'git clone {REPO}.git\ncd asd1-m2-13-stagewise\n# Otwórz index.html w przeglądarce.\nnode tests/run.cjs\nnode tools/benchmark.cjs') + '''<p>Po pobraniu ZIP wystarczy go rozpakować i otworzyć <code>index.html</code>. Node.js jest potrzebny tylko do automatycznych testów i benchmarku. Opcjonalny lokalny serwer: <code>python3 -m http.server 8000 --bind 127.0.0.1</code>. Nie jest konieczny do demonstracji.</p><h2>Odtworzenie kontroli przeglądarki i dokumentów</h2>''' + code('npm ci\nnpx playwright install chromium\nnpm run test:browser\npython3 tools/build_docs.py\nnode tools/export_pdf.cjs') + '''<p>Narzędzia używają przypiętych wersji Playwright i pdf-lib z <code>package-lock.json</code>. Generator treści wymaga Python 3, bez dodatkowych pakietów. Chromium potrzebuje bibliotek systemowych wymienionych w dokumentacji Playwright. Zmienne <code>PLAYWRIGHT_MODULE</code>, <code>PDF_LIB_MODULE</code> i <code>CHROMIUM_PATH</code> umożliwiają użycie wcześniej przygotowanych narzędzi.</p><h2>Środowisko weryfikacji</h2><p>Linux, Node.js 24.21.0, Python 3.12.3, Playwright 1.65.1 i Chromium 156. Testy przeglądarkowe otwierają rzeczywisty adres <code>file://</code> i blokują HTTP/HTTPS. Zrzuty interfejsu pochodzą z tego przebiegu, nie z makiety.</p>'''),
('Architektura i zapis danych', '''<p>Odpowiedzialności są rozdzielone. Funkcje obliczeniowe nie dotykają DOM ani localStorage. Walidacja nie pyta o potwierdzenie; interfejs zbiera zgodę i dopiero wtedy podmienia gotowy stan.</p><div class="architecture"><div>HTML + CSS<br><small>układ i dostępność</small></div><b>↓</b><div>ui.js → views.js<br><small>zdarzenia, formularze, bezpieczny tekst</small></div><b>↓</b><div>model.js ↔ algorithms.js<br><small>walidacja i transakcje · obliczenia i ranking</small></div><b>↓</b><div>storage.js / JSON<br><small>zapis pomocniczy i przenoszenie danych</small></div></div><p class="figlabel">Rysunek 1. Podział warstw aplikacji Stagewise.</p>''' + table(['Moduł', 'Odpowiedzialność'], [
['algorithms.js', 'różnice, sumy, ranking, porównanie, wyszukiwanie i ślad'],
['model.js', 'reguły danych, niezmienniki, atomowe transakcje'],
['timer.js / scenarios.js', 'pomiar czasu / powtarzalne dane kontrolne, graniczne i duże'],
['storage.js', 'odczyt i zapis lokalny, pobieranie pliku JSON'],
['views.js / ui.js', 'prezentacja wyniku / sterowanie i potwierdzenia'],
['tests/ i tools/', 'testy, benchmark, generowanie i kontrola dokumentów']
], 'Tabela 3. Odpowiedzialności plików.') + '''<h2>Atomowość operacji</h2><p>Transakcja kopiuje dane, wykonuje zmianę i sprawdza cały kandydat. Dopiero poprawny obiekt zastępuje stan w pamięci. Błędny import, brakujące czasy i niedozwolona edycja pozostawiają oryginał nietknięty. Wyniki są liczone ponownie po edycji, bez starego rankingu.</p><p>localStorage jest dodatkiem: dla file:// zachowanie zależy od przeglądarki, a przy dużych danych może zabraknąć limitu. Błąd zapisu jest widoczny, dane pozostają w pamięci. Podstawową kopią pracy jest eksport JSON. Limit pliku importu to 32 MB.</p>'''),
('Obsługa i przykład kontrolny', figure('compare.png', 'Rysunek 2. Własny zrzut: porównanie prób A i B w działającym interfejsie.', 240) + '''<p>Ścieżka: <strong>Plan wystąpienia → Nowa próba → Historia prób → Porównanie</strong>. W nowej próbie wybieramy część, uruchamiamy stoper i zatrzymujemy go, aby wpisać sekundy. Dopuszczalny jest także ręczny wpis. Po uzupełnieniu wszystkich części zapisujemy próbę i notatkę.</p>''' + table(['Część', 'Plan', 'A', 'Δ A', 'B', 'Δ B'], [['Wstęp',60,70,'+10',60,0],['Treść',180,200,'+20',185,'+5'],['Zakończenie',60,50,'−10',55,'−5'],['Razem',300,320,'+20',300,0]], 'Tabela 4. Kontrolne dane i wyniki w sekundach.') + '''<p>Próba A: |10| + |20| + |−10| = <strong>40 s</strong>. Ranking: treść, wstęp, zakończenie. Wstęp i zakończenie mają równy moduł, więc rozstrzyga kolejność. Próba B: 0 + 5 + 5 = <strong>10 s</strong>. B jest bliższa planowi o 40−10 = <strong>30 s</strong>.</p>''' + box('Przykład pośredni: dla treści A odejmujemy 180 od 200, otrzymując +20 s. To największy moduł, więc treść zajmuje pierwsze miejsce rankingu. Zmień w B wstęp z 60 na 90 s: wynik B wzrośnie do 40 s i pojawi się remis.') + '''<p>Na pulpicie kolorom towarzyszą podpisy „za długo”, „za krótko” i „zgodnie”. Formularze mają etykiety, obsługę klawiaturą oraz widoczny fokus. Układ został sprawdzony przy szerokościach 390, 768 i 1512 px.</p>'''),
('Doświadczenia i interpretacja', benchmark_table + '''<p>Dane uporządkowane są już w kolejności docelowego rankingu. Każda nowa pozycja kończy pętlę po pierwszym porównaniu. Dla odwróconych klucz przesuwa cały dotychczasowy prefiks: 1+2+…+(n−1). Dlatego dla 1000 rekordów otrzymujemy 999 wobec 499 500 porównań. Nie są to pomiary czasu zegarowego.</p><p>Powtarzalny generator LCG używa ziarna 13013 i wzoru <code>x ← (1664525·x + 1013904223) mod 2³²</code>. Moduły odchyleń i kolejność determinują jednoznaczny wynik. W każdym wierszu własne sortowanie porównano z niezależnym wzorcem testowym <code>Array.sort</code>; metoda biblioteczna nie zastępuje algorytmu w aplikacji.</p>''' + search_table + '''<p>Wyszukiwanie jest liniowe: brak wyniku wymaga sprawdzenia całej listy. Wcześniejszy zwrot ogranicza koszt trafienia na początku. Liczniki odpowiadają rzeczywistym iteracjom, nie długości listy dopisanej po zakończeniu.</p>''' + box('ΣΔ może wynosić zero, mimo błędnych proporcji. Dla [80,160,60] przy planie [60,180,60] mamy Δ=[+20,−20,0], ΣΔ=0, ale Σ|Δ|=40. Całkowity czas nie wystarcza do oceny planu.') + f'<p class="small">Dane źródłowe: results/benchmark.json. Faktyczne wykonanie: {E(BENCH["executedAt"])}.</p>'),
('Testy i wyniki weryfikacji', f'''<p>Testy domenowe: <strong>{TESTS['passed']}/{TESTS['total']} PASS</strong>. Kontrole przeglądarkowe: <strong>{BROWSER['passed']}/{BROWSER['total']} PASS</strong>. Każdy przypadek ma wejście, oczekiwanie i asercję. Poniżej wybrane jawne wyniki; pełna lista znajduje się w results/tests.json i results/browser.json.</p>''' + table(['Wejście / przypadek', 'Oczekiwany wynik', 'Rzeczywisty'], [
['Kontrolny A: 70,200,50', '320 s; Σ|Δ|=40; T,W,Z', 'zgodny · PASS'],
['Kontrolny B: 60,185,55', '300 s; Σ|Δ|=10; B o 30 s', 'zgodny · PASS'],
['Brak czasu zakończenia', 'odrzucenie, brak zmiany stanu', 'zgodny · PASS'],
['60,180,60', 'Σ|Δ|=0', '0 · PASS'],
['80,160,60', 'ΣΔ=0; Σ|Δ|=40', '0; 40 · PASS'],
['Równe moduły: 10 i −10', 'kolejność części rozstrzyga', 'W przed Z · PASS'],
['Równe wyniki prób', 'brak zwycięzcy', 'null · PASS'],
['Pusta lista', 'brak błędu, licznik 0', 'zgodny · PASS'],
['Eksport → import', 'te same dane i obliczenia', 'zgodny · PASS'],
['Błędny JSON / plan 0 / czas 7201', 'odrzucenie bez zapisu', 'zgodny · PASS'],
['Sort: uporządk., odwrotne, remis', 'zgodność z niezależnym wzorcem', 'zgodny · PASS'],
['1000 części i 1000 prób', 'akceptacja; 1001 części odrzucone', 'zgodny · PASS']
], 'Tabela 7. Wybrane wejścia, oczekiwania i rzeczywiste wyniki.') + '''<h2>Co dodatkowo sprawdzono w przeglądarce</h2><p>Start/stop/wznowienie stopera, zapis i edycję, anulowanie importu, odrzucenie błędnego pliku, eksport pobranego JSON, potwierdzenie usunięcia prób przy zmianie planu, przesuwanie części, Enter w formularzu, puste widoki, złośliwy tekst HTML, duży zestaw i brak poziomego przepełnienia na telefonie. Nie wystąpiły błędy JavaScript ani żądania sieciowe.</p><h2>Poprawki podczas przygotowania</h2><p>W kontroli ręcznej poprawiono przesuwanie części w górę. Dla dużej historii wydzielono liniowe podsumowanie bez zbędnego sortowania każdej próby. Pierwsza kontrola dużego zestawu czekała na komunikat sukcesu, chociaż UI poprawnie ostrzegał o limicie localStorage; asercję poprawiono, aby sprawdzała rzeczywisty stan i liczbę rekordów.</p>'''),
('Wnioski, źródła i wkład', '''<h2>Wnioski</h2><p>Najważniejszą informacją jest suma bezwzględnych odchyleń, a nie sam czas łączny. Ranking przekłada tę miarę na praktyczne wskazówki. Prosta lista rekordów i jawne algorytmy są wystarczające dla zakresu projektu; licznik pokazuje różnicę między liniowym wyszukiwaniem a kwadratowym najgorszym przypadkiem sortowania.</p><h2>Ograniczenia i możliwy rozwój</h2><p>Aplikacja ocenia czas, nie retorykę ani jakość argumentów. Brak synchronizacji, kont i rozpoznawania mowy jest świadomym ograniczeniem zakresu. Stoper liczy pełne sekundy i używa zegara performance.now; uśpienie systemu może zależeć od implementacji przeglądarki. Dla długich lub ważnych prób należy zweryfikować wynik ręcznie. Nie należy polegać wyłącznie na localStorage.</p><p>Możliwe rozszerzenia to statystyki mediany odchyleń i archiwizacja wersji planu. Dobrowolny wykres postępu został już dodany. Nie zastępuje on wymaganych tabel i obliczeń.</p><h2>AI i rzeczywisty wkład</h2><p>Wykorzystano asystenta OpenAI Codex w OpenClaw do przygotowania kodu, stylu, testów, generatora dokumentów i materiałów do obrony. Automatyczne testy i zrzuty uruchomił asystent. Zlecający wybrał temat oraz kierunek wyglądu: czerwienie i ciemne szarości, a także dostarczył logotypy UwB. Nie przypisujemy studentowi niepotwierdzonych samodzielnych zmian ani wykonania testów.</p><p>Przed oddaniem autor powinien samodzielnie przeczytać kod, uruchomić program i testy oraz przećwiczyć zmianę danych i reguły porównania. Przygotowane notatki wyjaśniają fragmenty wymagane na obronie.</p><h2>Źródła</h2><ol class="sources"><li>Karta zadania ASD1-M2-13, Dziennik UwB, 2026/2027; kopia: docs/assignment.html. Reguły, przykład kontrolny i wymagania oddania.</li><li><a href="https://developer.mozilla.org/en-US/docs/Web/API/Performance/now">MDN: Performance.now()</a> — pomiar czasu.</li><li><a href="https://developer.mozilla.org/en-US/docs/Web/API/Window/localStorage">MDN: Window.localStorage</a> — zapis przeglądarkowy i ograniczenia file://.</li><li><a href="https://docs.github.com/en/repositories/creating-and-managing-repositories/quickstart-for-repositories">GitHub Docs: Quickstart for repositories</a> — repozytorium i commit.</li></ol><p class="small">Źródła internetowe sprawdzono 19.11.2026. Implementacje wyszukiwania i sortowania opracowano dla tego projektu; nie skopiowano gotowej biblioteki.</p>''')
]

