slide_script = '''let current=0;const slides=[...document.querySelectorAll('.slide')];function show(n){current=Math.max(0,Math.min(slides.length-1,n));slides.forEach((s,i)=>{s.classList.toggle('active',i===current);s.setAttribute('aria-hidden',String(i!==current))});document.querySelector('#counter').textContent=(current+1)+' / '+slides.length}function resize(){document.documentElement.style.setProperty('--scale',Math.min(innerWidth/1280,(innerHeight-74)/720))}document.querySelector('#prev').onclick=()=>show(current-1);document.querySelector('#next').onclick=()=>show(current+1);document.querySelector('#fullscreen').onclick=()=>{if(document.fullscreenElement)document.exitFullscreen();else document.documentElement.requestFullscreen?.()};document.addEventListener('keydown',e=>{if(['ArrowRight','ArrowLeft',' ','Home','End'].includes(e.key)){e.preventDefault();if(e.key==='Home')show(0);else if(e.key==='End')show(9);else show(current+(e.key==='ArrowLeft'?-1:1))}});addEventListener('resize',resize);resize();show(0);'''


