    return f'<section class="slide {cls}" aria-label="Slajd {index+1}"><header class="slide-top"><img src="../assets/mark.svg" alt=""><span>stagewise.</span><div class="slide-academic"><span>ASD I / M2</span><img class="slide-filia" src="../assets/uwb-vilnius.png" alt="Filia UwB w Wilnie"><img class="slide-seal" src="../assets/uwb-seal.png" alt="Herb UwB"></div></header><div class="page-content"><p class="eyebrow">{index+1:02d} / ' + ['CEL','PROBLEM','ZAKRES','MODEL DANYCH','ALGORYTM','TECHNOLOGIA','INTERFEJS','TESTY','WNIOSKI','POKAZ'][index] + f'</p><h1>{E(title).replace(chr(10), "<br>")}</h1>{content}</div><footer><span>{AUTHOR} · ASD1-M2-13</span><span>{index+1:02d} / 10</span></footer></section>'


